/* ══════════════════════════════════════════════════════════════
   格式化工具
══════════════════════════════════════════════════════════════ */
function fmtMoney(n) { return 'CA$ ' + (Number.isInteger(n) ? n : Number(n).toFixed(2)); }
function fmtISODate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  return (d.getMonth() + 1) + '月' + d.getDate() + '日';
}

/* ══════════════════════════════════════════════════════════════
   数据（先用 demo，登录后替换为 Supabase 数据）
══════════════════════════════════════════════════════════════ */
let bills = [];

let N = bills.length;

/* 登录后从 Supabase 加载真实数据 */
(async () => {
  try {
    const user = await DB.getCurrentUser();
    if (!user) { console.log('[Load] 无用户，跳过加载'); return; }
    console.log('[Load] 正在从 Supabase 拉取账单...');
    const remoteBills = await DB.fetchMyBills();
    console.log('[Load] 拉取到', remoteBills.length, '条账单:', remoteBills);
    await markBillsWithProofs(remoteBills);
    // 用动画重建轮播
    rebuildCarousel(remoteBills, true);
  } catch (e) {
    console.error('[Load] Supabase 数据加载失败:', e);
  }
})();

/* ══════════════════════════════════════════════════════════════
   动画参数
══════════════════════════════════════════════════════════════ */
const CFG = {
  STEP: 148,
  DRAG_PX: 72,
  SCALE_STEP: 0.13,
  MIN_SCALE: 0.60,
  Y_STEP: 14,
  OPACITY_STEP: 0.26,
  SNAP_DUR: 420,
  POP_SCALE: 1.08,  // 选中弹跳放大倍数
  POP_DUR: 280,   // 选中弹跳时长 ms
  popMode: 'all', // 'single' = 仅居中卡片放大, 'all' = 整行滑过再回弹
  INERTIA_DUR: 500,  // 惯性滑行持续时间 ms
  INERTIA_RATIO: 0.35, // 惯性速度比例（乘以滑动速度）
  showShadow: true,
  showFPS: false,
  showTexture: true,
  showSheen: true,
  cycle: false, // 无限循环
  // 曲线指数：1.0 = 线性, >1 = 中心缓慢/边缘加速, <1 = 中心快/边缘缓
  curveX: 0.8,   // 位移曲线
  curveScale: 2.4,   // 缩放曲线
  curveY: 1.7,   // 下沉曲线
  curveOpacity: 1.7,   // 透明度曲线
};

/* ══════════════════════════════════════════════════════════════
   DOM 构建：卡片 / 指示点
══════════════════════════════════════════════════════════════ */
const stage = document.getElementById('stage');
const dotsEl = document.getElementById('dots');

function createCard(b, i) {
  const el = document.createElement('div');
  el.className = 'bill-card';
  el.dataset.idx = i;

  // 判断角色：我是垫付人 → 收款；我是分摊人 → 待付款
  const isPayer = currentUserId && b.payer_id === currentUserId;
  const otherCount = (b.members || []).filter(m => m.id !== b.payer_id).length;
  const collectTotal = (b.items || []).reduce((sum, item) => {
    const n = (item.members || []).length || 1;
    const otherShare = (item.members || []).filter(m => m.id !== b.payer_id).length;
    return sum + (item.price * (item.qty || 1) / n) * otherShare;
  }, 0);
  const myShare = b.my_share || b.per_amount;

  let roleTagHtml, heroLabel, heroAmount;
  if (b.settled) {
    roleTagHtml = '<div class="card-role-tag settled">✓ 已结清</div>';
    heroLabel = isPayer ? `已收回` : `已支付`;
    heroAmount = isPayer ? collectTotal : myShare;
  } else if (isPayer) {
    roleTagHtml = '<div class="card-role-tag collect">💰 待收款</div>';
    heroLabel = `向 ${otherCount} 人收`;
    heroAmount = collectTotal;
  } else if (b._hasMeProof) {
    roleTagHtml = '<div class="card-role-tag paid">✓ 已付款</div>';
    heroLabel = `已支付`;
    heroAmount = myShare;
  } else {
    roleTagHtml = '<div class="card-role-tag pay">📤 待付款</div>';
    heroLabel = `你要付`;
    heroAmount = myShare;
  }

  el.innerHTML = `
    <div class="card-bg" style="background:${b.color}"></div>
    <div class="card-highlight"></div>
    <div class="card-noise"></div>
    <div class="card-inner">
      <div class="card-top">
        <div class="card-icon-box">${b.icon}</div>
        <div class="card-top-right">
          <div class="card-date-label">${fmtISODate(b.date)}</div>
          ${roleTagHtml}
        </div>
      </div>
      <div class="card-amount-section">
        <div class="card-label-title">${b.title}</div>
        <div class="card-hero-label">${heroLabel}</div>
        <div class="card-amount-num">${fmtMoney(heroAmount)}</div>
        <div class="card-per-line">总计 <em>${fmtMoney(b.total_amount)}</em></div>
      </div>
      <div class="card-bottom-row">
        <div class="card-avs">${(b.members || []).map(m => `<div class="cav">${typeof m === 'string' ? m : m.emoji}</div>`).join('')}</div>
        <div class="card-pill ${b.settled ? 'ok' : 'ng'}">${b.settled ? '✓ 已结清' : '待结算'}</div>
      </div>
    </div>`;
  stage.appendChild(el);
  return el;
}

function createDot() {
  const d = document.createElement('div');
  d.className = 'dot';
  dotsEl.appendChild(d);
  return d;
}

let cardEls = bills.map((b, i) => createCard(b, i));
let dotEls = bills.map(() => createDot());

async function markBillsWithProofs(billList) {
  if (!currentUserId) return;
  try {
    const { data } = await DB.sb
      .from('payment_proofs')
      .select('bill_id, user_id');
    if (!data) return;
    const proofSet = new Set(data.map(p => `${p.bill_id}_${p.user_id}`));
    billList.forEach(b => {
      b._hasMeProof = proofSet.has(`${b.id}_${currentUserId}`);
    });
  } catch (e) { console.error('markBillsWithProofs:', e); }
}

function updateSummary(billList) {
  let total = 0, collect = 0, owe = 0;
  billList.forEach(b => {
    total += b.total_amount || 0;
    const isPayer = currentUserId && b.payer_id === currentUserId;
    if (isPayer) {
      // 我垫付的，算应收
      const others = (b.items || []).reduce((sum, item) => {
        const n = (item.members || []).length || 1;
        const otherShare = (item.members || []).filter(m => m.id !== b.payer_id).length;
        return sum + (item.price * (item.qty || 1) / n) * otherShare;
      }, 0);
      if (!b.settled) collect += others;
    } else {
      // 我要付的
      if (!b.settled) owe += (b.my_share || 0);
    }
  });
  const sumTotalEl = document.getElementById('sumTotal');
  const sumCollectEl = document.getElementById('sumCollect');
  const sumOweEl = document.getElementById('sumOwe');
  if (sumTotalEl) sumTotalEl.textContent = fmtMoney(total);
  if (sumCollectEl) sumCollectEl.textContent = '+' + fmtMoney(collect);
  if (sumOweEl) sumOweEl.textContent = '-' + fmtMoney(owe);
}

function rebuildCarousel(billList, animate) {
  stage.innerHTML = '';
  dotsEl.innerHTML = '';
  bills = billList;
  N = bills.length;
  updateSummary(billList);
  cardEls = bills.map((b, i) => createCard(b, i));
  dotEls = bills.map(() => createDot());
  current = 0;
  fracLive = 0;

  if (animate && N > 0) {
    // Staggered pop-in animation
    cardEls.forEach(c => c.classList.add('scale-pop'));
    cardEls.forEach(el => { el.style.transition = 'none'; });
    render(0);
    const STAGGER = 80;
    cardEls.forEach((card, i) => {
      setTimeout(() => {
        requestAnimationFrame(() => card.classList.add('pop-go'));
      }, i * STAGGER + 50);
    });
    setTimeout(() => {
      cardEls.forEach(c => c.classList.remove('scale-pop', 'pop-go'));
      snapTo(0);
    }, N * STAGGER + 500);
  } else {
    if (typeof snapTo === 'function') snapTo(0);
  }
}

/* ══════════════════════════════════════════════════════════════
   滑动音效引擎
══════════════════════════════════════════════════════════════ */
const SFX = {
  enabled: true,
  volume: 0.6,
  sounds: [],       // AudioBuffer[]
  current: 0,        // 当前选中的音效索引
  names: [],       // 文件名列表
  lastInt: 0,        // 上一次经过的整数位置（用于检测跨越）
};

let audioCtx = null;
function getAudioCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  return audioCtx;
}

function playSfx() {
  if (!SFX.enabled || SFX.sounds.length === 0) return;
  const ctx = getAudioCtx();
  if (ctx.state === 'suspended') ctx.resume();
  const src = ctx.createBufferSource();
  const gain = ctx.createGain();
  src.buffer = SFX.sounds[SFX.current % SFX.sounds.length];
  gain.gain.value = SFX.volume;
  src.connect(gain).connect(ctx.destination);
  src.start();
}

// 检测 frac 是否跨过了新的整数边界
function checkSfxTrigger(frac) {
  const nearest = Math.round(frac);
  if (nearest !== SFX.lastInt) {
    SFX.lastInt = nearest;
    playSfx();
  }
}

// 加载音频文件（File 对象）
async function loadSoundFile(file) {
  const ctx = getAudioCtx();
  const buf = await file.arrayBuffer();
  const audio = await ctx.decodeAudioData(buf);
  SFX.sounds.push(audio);
  SFX.names.push(file.name.replace(/\.[^.]+$/, ''));
  // 默认选最新加的
  SFX.current = SFX.sounds.length - 1;
  updateSoundLabel();
}

function updateSoundLabel() {
  const el = document.getElementById('sound-name');
  if (SFX.names.length === 0) {
    el.textContent = '无';
  } else {
    el.textContent = `${SFX.current + 1}/${SFX.sounds.length} ${SFX.names[SFX.current]}`;
  }
}

// 从 base64 data URI 加载内置音效
async function loadBuiltinSound(dataUri, name) {
  const ctx = getAudioCtx();
  const resp = await fetch(dataUri);
  const buf = await resp.arrayBuffer();
  const audio = await ctx.decodeAudioData(buf);
  SFX.sounds.push(audio);
  SFX.names.push(name);
  updateSoundLabel();
}

// 内置音效（base64 嵌入）
const BUILTIN_SOUNDS = [
  { name: '滑动01', src: 'data:audio/wav;base64,' },
  { name: '滑动02', src: 'data:audio/wav;base64,' },
  { name: '滑动03', src: 'data:audio/wav;base64,' },
];

/* ══════════════════════════════════════════════════════════════
   核心渲染
══════════════════════════════════════════════════════════════ */
let fracLive = 0;

// 调试面板状态（需在 render() 调用前声明）
let debugOpen = false;
let logoClickCnt = 0;
let logoClickTs = 0;

/* 辅助：将任意整数/浮点数 wrap 到 [0, N) */
function wrapN(v) { return ((v % N) + N) % N; }

function render(frac) {
  // 检测是否跨过整数边界 → 播放音效
  checkSfxTrigger(frac);

  fracLive = frac;

  // cycle 模式下，frac 可超出 [0,N-1]，用 modulo 折算视觉位置
  const fracW = CFG.cycle ? wrapN(frac) : frac;

  cardEls.forEach((el, i) => {
    let offset = i - fracW;
    if (CFG.cycle) {
      // 取最短圆弧方向（wrap 到 [-N/2, N/2]）
      if (offset > N / 2) offset -= N;
      if (offset < -N / 2) offset += N;
    }
    const absO = Math.abs(offset);
    const sign = Math.sign(offset);

    // 各属性独立走幂曲线：pow(absO, exponent)
    // exponent=1 → 线性 | >1 → 中心变化慢,边缘加速 | <1 → 中心变化快
    const cX = Math.pow(absO, CFG.curveX);
    const cS = Math.pow(absO, CFG.curveScale);
    const cY = Math.pow(absO, CFG.curveY);
    const cO = Math.pow(absO, CFG.curveOpacity);

    const x = sign * cX * CFG.STEP;
    const y = cY * CFG.Y_STEP;
    const scale = Math.max(CFG.MIN_SCALE, 1 - cS * CFG.SCALE_STEP);
    const op = Math.max(0.28, 1 - cO * CFG.OPACITY_STEP);

    el.style.transform = `translateX(${x}px) translateY(${y}px) scale(${scale})`;
    el.style.opacity = op;
    el.style.zIndex = Math.round(50 - absO * 10);

    el.classList.remove('shadow-active', 'shadow-side', 'no-shadow');
    if (!CFG.showShadow) {
      el.classList.add('no-shadow');
    } else if (absO < 0.5) {
      el.classList.add('shadow-active');
    } else if (absO < 1.6) {
      el.classList.add('shadow-side');
    }
  });

  const ci = CFG.cycle
    ? Math.round(wrapN(frac))
    : Math.max(0, Math.min(N - 1, Math.round(frac)));
  dotEls.forEach((d, i) => {
    const shouldOn = (i === ci);
    if (shouldOn !== d.classList.contains('on')) d.classList.toggle('on', shouldOn);
  });

  if (debugOpen) {
    document.getElementById('dbg-frac').textContent = frac.toFixed(3);
    document.getElementById('dbg-cur').textContent = current;
  }
}

/* ══════════════════════════════════════════════════════════════
   RAF 节流
══════════════════════════════════════════════════════════════ */
let rafId = null;
let pendFrac = 0;

function scheduleRender(frac) {
  pendFrac = frac;
  if (rafId) return;
  rafId = requestAnimationFrame(() => { rafId = null; render(pendFrac); });
}

/* ══════════════════════════════════════════════════════════════
   Snap
══════════════════════════════════════════════════════════════ */
let current = 0;

let popTimer1 = null;
let popTimer2 = null;

function snapTo(idx) {
  const oldCurrent = current;
  if (CFG.cycle) {
    current = Math.round(wrapN(idx));
  } else {
    idx = Math.max(0, Math.min(N - 1, idx));
    current = idx;
  }
  cardEls.forEach(el => {
    el.style.transition = `transform ${CFG.SNAP_DUR}ms cubic-bezier(.25,.46,.45,.94), opacity ${CFG.SNAP_DUR}ms ease`;
  });
  render(idx);
  playSfx(); // snap 居中时播放音效

  // 清理之前的弹跳定时器
  if (popTimer1) { clearTimeout(popTimer1); popTimer1 = null; }
  if (popTimer2) { clearTimeout(popTimer2); popTimer2 = null; }

  // 切换到新卡片时播放弹跳
  if (current !== oldCurrent) {
    if (CFG.popMode === 'all') {
      // 模式 A：整行滑过目标再回弹（模拟惯性过冲）
      const dir = current > oldCurrent ? 1 : -1;
      const overshoot = (CFG.POP_SCALE - 1);  // 复用 POP_SCALE 控制过冲幅度
      const overIdx = idx + dir * overshoot;

      // 先滑到过冲位置
      render(overIdx);

      popTimer1 = setTimeout(() => {
        // 再回弹到精确目标
        cardEls.forEach(el => {
          el.style.transition = `transform ${CFG.POP_DUR}ms cubic-bezier(.25,.46,.45,.94), opacity ${CFG.POP_DUR}ms ease`;
        });
        render(idx);
      }, CFG.SNAP_DUR);
    } else {
      // 模式 B：仅居中卡片放大再缩回
      const targetEl = cardEls[current];
      if (targetEl) {
        popTimer1 = setTimeout(() => {
          targetEl.style.transition = `transform ${CFG.POP_DUR / 2}ms cubic-bezier(.25,.46,.45,.94)`;
          targetEl.style.transform = `translateX(0px) translateY(0px) scale(${CFG.POP_SCALE})`;

          popTimer2 = setTimeout(() => {
            targetEl.style.transition = `transform ${CFG.POP_DUR / 2}ms cubic-bezier(.25,.46,.45,.94)`;
            targetEl.style.transform = `translateX(0px) translateY(0px) scale(1)`;
          }, CFG.POP_DUR / 2);
        }, CFG.SNAP_DUR);
      }
    }
  }

  if (CFG.cycle) {
    setTimeout(() => { fracLive = current; }, CFG.SNAP_DUR + CFG.POP_DUR + 60);
  }
}

/* ══════════════════════════════════════════════════════════════
   拖动手势
══════════════════════════════════════════════════════════════ */
let dragging = false;
let startX = 0;
let startFrac = 0;
let touchStartTime = 0;
let touchStartX = 0;
let inertiaRafId = null;

// 保留最近若干采样点，用于计算松手速度
const VELOCITY_WINDOW = 80; // 只看最近 80ms 内的采样
let moveHistory = []; // { x, t }

function onDragStart(x) {
  if (inertiaRafId) { cancelAnimationFrame(inertiaRafId); inertiaRafId = null; }
  dragging = true; startX = x; touchStartX = x;
  startFrac = fracLive; touchStartTime = Date.now();
  moveHistory = [{ x, t: Date.now() }];
  stage.classList.add('dragging');
  cardEls.forEach(el => { el.style.transition = 'none'; });
}

function onDragMove(x) {
  if (!dragging) return;
  const now = Date.now();
  moveHistory.push({ x, t: now });
  // 只保留窗口内的采样
  while (moveHistory.length > 2 && now - moveHistory[0].t > VELOCITY_WINDOW) {
    moveHistory.shift();
  }
  const dx = x - startX;
  const raw = startFrac - dx / CFG.DRAG_PX;
  const frac = CFG.cycle ? raw : Math.max(0, Math.min(N - 1, raw));
  scheduleRender(frac);
}

function onDragEnd(x) {
  if (!dragging) return;
  dragging = false;
  stage.classList.remove('dragging');

  const dx = x - startX;
  const duration = Date.now() - touchStartTime;

  // 点击检测
  if (Math.abs(dx) < 8 && duration < 250) {
    const stageRect = stage.getBoundingClientRect();
    const clickX = x - stageRect.left - stageRect.width / 2;
    const clickedCard = Math.round(current + (clickX / CFG.STEP));
    const target = CFG.cycle
      ? clickedCard
      : Math.max(0, Math.min(N - 1, clickedCard));

    // 点击当前卡片 → 弹跳动画 → 打开详情
    if (target === current && cardEls[current]) {
      const card = cardEls[current];
      card.style.transition = 'transform .15s cubic-bezier(.34,1.56,.64,1)';
      card.style.transform += ' scale(0.95)';
      setTimeout(() => {
        card.style.transition = 'transform .35s cubic-bezier(.34,1.56,.64,1)';
        snapTo(current);
        if (bills[current]) openDetail(bills[current]);
      }, 120);
    } else {
      snapTo(target);
    }
    return;
  }

  // 把松手点也加入历史
  moveHistory.push({ x, t: Date.now() });

  // 用历史窗口首尾计算速度（px/s → frac/s）
  const oldest = moveHistory[0];
  const newest = moveHistory[moveHistory.length - 1];
  const dt = Math.max(1, newest.t - oldest.t); // ms
  const dxRecent = newest.x - oldest.x;         // px
  const velocity = -(dxRecent / CFG.DRAG_PX) / (dt / 1000); // frac/s

  // 惯性滑行：用 RAF 逐帧减速
  const inertiaStart = performance.now();
  const startVelocity = velocity * CFG.INERTIA_RATIO;
  const inertiaDur = CFG.INERTIA_DUR;
  const inertiaStartF = fracLive;

  function inertiaStep(now) {
    const elapsed = now - inertiaStart;
    const t = Math.min(1, elapsed / inertiaDur);
    // ease-out 减速：v(t) = v0 * (1-t)^2 → 位移 = v0 * dur * (t - t²/2 + t³/3) ... 简化用积分
    // 简单用 easeOut: displacement = v0 * dur/1000 * (t - t²/2) * 2 归一化
    const easeT = t * (2 - t); // ease-out quadratic: 0→0, 1→1
    const displacement = startVelocity * (inertiaDur / 1000) * easeT * 0.5;
    let frac = inertiaStartF + displacement;
    if (!CFG.cycle) frac = Math.max(0, Math.min(N - 1, frac));

    cardEls.forEach(el => { el.style.transition = 'none'; });
    render(frac);

    if (t < 1) {
      inertiaRafId = requestAnimationFrame(inertiaStep);
    } else {
      inertiaRafId = null;
      // 惯性结束 → snap 到最近整数卡片
      let target = Math.round(frac);
      if (!CFG.cycle) target = Math.max(0, Math.min(N - 1, target));
      snapTo(target);
    }
  }

  // 如果速度太小直接 snap
  if (Math.abs(startVelocity) < 0.3) {
    let target = Math.round(fracLive);
    if (!CFG.cycle) target = Math.max(0, Math.min(N - 1, target));
    snapTo(target);
  } else {
    inertiaRafId = requestAnimationFrame(inertiaStep);
  }
}

/* ══════════════════════════════════════════════════════════════
   事件绑定
══════════════════════════════════════════════════════════════ */
stage.addEventListener('mousedown', e => { onDragStart(e.clientX); e.preventDefault(); });
document.addEventListener('mousemove', e => { if (dragging) onDragMove(e.clientX); });
document.addEventListener('mouseup', e => { if (dragging) onDragEnd(e.clientX); });

stage.addEventListener('touchstart', e => { onDragStart(e.touches[0].clientX); }, { passive: true });
stage.addEventListener('touchmove', e => {
  if (!dragging) return;
  e.preventDefault();
  onDragMove(e.touches[0].clientX);
}, { passive: false });
