/* ══════════════════════════════════════════════════════════════
   月度账单分组（📌 Pushpin Feature）
══════════════════════════════════════════════════════════════ */
function isoToMonthKey(iso) {
  const d = new Date(iso);
  return `${d.getMonth() + 1}月`;
}

let viewMode = 'all'; // 'all' | 'months' | 'month-detail'
let currentMonthKey = null;
let monthPileEls = [];
let monthDotEls = [];
let monthKeys = [];
let monthGroups = {};
let monthN = 0;

const monthStage = document.getElementById('month-stage');
const clipBtn = document.getElementById('clip-btn');
const backBtn = document.getElementById('back-btn');
const sectionLabel = document.getElementById('section-label');

function groupBillsByMonth() {
  monthGroups = {};
  bills.forEach(b => {
    const key = isoToMonthKey(b.date);
    if (!monthGroups[key]) monthGroups[key] = [];
    monthGroups[key].push(b);
  });
  const monthOrder = ['12月', '11月', '10月', '9月', '8月', '7月', '6月', '5月', '4月', '3月', '2月', '1月'];
  monthKeys = Object.keys(monthGroups).sort((a, b) => monthOrder.indexOf(a) - monthOrder.indexOf(b));
  monthN = monthKeys.length;
}

function createMonthPile(key, billsInMonth, idx) {
  const el = document.createElement('div');
  el.className = 'month-pile';
  el.dataset.idx = idx;
  el.dataset.month = key;
  const total = billsInMonth.reduce((sum, b) => sum + (b.total_amount || 0), 0);
  const icons = [...new Set(billsInMonth.map(b => b.icon))].slice(0, 5);
  el.innerHTML = `
        <div class="pile-pin">📌</div>
        <div class="pile-card">
          <div class="pile-month-label">${key}</div>
          <div class="pile-year">所有账单</div>
          <div class="pile-divider"></div>
          <div class="pile-count">${billsInMonth.length} 笔账单</div>
          <div class="pile-total">¥ ${total.toLocaleString('zh-CN', { minimumFractionDigits: 0 })}</div>
          <div class="pile-icons">${icons.map(i => `<span>${i}</span>`).join('')}</div>
        </div>`;
  monthStage.appendChild(el);
  return el;
}

// Month pile carousel engine
let mFracLive = 0, mCurrent = 0, mDragging = false;
let mStartX = 0, mStartFrac = 0, mTouchStartTime = 0, mTouchStartX = 0;
let mInertiaRafId = null, mMoveHistory = [], mRafId = null, mPendFrac = 0;

function renderMonths(frac) {
  mFracLive = frac;
  monthPileEls.forEach((el, i) => {
    const offset = i - frac;
    const absO = Math.abs(offset);
    const sign = Math.sign(offset);
    const x = sign * Math.pow(absO, CFG.curveX) * CFG.STEP;
    const y = Math.pow(absO, CFG.curveY) * CFG.Y_STEP;
    const scale = Math.max(CFG.MIN_SCALE, 1 - Math.pow(absO, CFG.curveScale) * CFG.SCALE_STEP);
    const op = Math.max(0.28, 1 - Math.pow(absO, CFG.curveOpacity) * CFG.OPACITY_STEP);
    el.style.transform = `translateX(${x}px) translateY(${y}px) scale(${scale})`;
    el.style.opacity = op;
    el.style.zIndex = Math.round(50 - absO * 10);
    el.classList.remove('shadow-active', 'shadow-side');
    if (absO < 0.5) el.classList.add('shadow-active');
    else if (absO < 1.6) el.classList.add('shadow-side');
  });
  const ci = Math.max(0, Math.min(monthN - 1, Math.round(frac)));
  monthDotEls.forEach((d, i) => {
    const on = (i === ci);
    if (on !== d.classList.contains('on')) d.classList.toggle('on', on);
  });
}

function scheduleRenderMonths(frac) {
  mPendFrac = frac;
  if (mRafId) return;
  mRafId = requestAnimationFrame(() => { mRafId = null; renderMonths(mPendFrac); });
}

function snapToMonth(idx) {
  idx = Math.max(0, Math.min(monthN - 1, idx));
  mCurrent = idx;
  monthPileEls.forEach(el => {
    el.style.transition = `transform ${CFG.SNAP_DUR}ms cubic-bezier(.25,.46,.45,.94), opacity ${CFG.SNAP_DUR}ms ease`;
  });
  renderMonths(idx);
  setTimeout(() => { mFracLive = mCurrent; }, CFG.SNAP_DUR + 60);
}

function onMonthDragStart(x) {
  if (mInertiaRafId) { cancelAnimationFrame(mInertiaRafId); mInertiaRafId = null; }
  mDragging = true; mStartX = x; mTouchStartX = x;
  mStartFrac = mFracLive; mTouchStartTime = Date.now();
  mMoveHistory = [{ x, t: Date.now() }];
  monthStage.classList.add('dragging');
  monthPileEls.forEach(el => { el.style.transition = 'none'; });
}

function onMonthDragMove(x) {
  if (!mDragging) return;
  const now = Date.now();
  mMoveHistory.push({ x, t: now });
  while (mMoveHistory.length > 2 && now - mMoveHistory[0].t > VELOCITY_WINDOW) mMoveHistory.shift();
  const dx = x - mStartX;
  const frac = Math.max(0, Math.min(monthN - 1, mStartFrac - dx / CFG.DRAG_PX));
  scheduleRenderMonths(frac);
}

function onMonthDragEnd(x) {
  if (!mDragging) return;
  mDragging = false;
  monthStage.classList.remove('dragging');
  const dx = x - mStartX;
  const duration = Date.now() - mTouchStartTime;

  if (Math.abs(dx) < 8 && duration < 250) {
    const rect = monthStage.getBoundingClientRect();
    const clickX = x - rect.left - rect.width / 2;
    const clicked = Math.round(mCurrent + (clickX / CFG.STEP));
    const target = Math.max(0, Math.min(monthN - 1, clicked));
    if (target === mCurrent) {
      enterMonthDetail(monthKeys[mCurrent]);
    } else {
      snapToMonth(target);
    }
    return;
  }

  mMoveHistory.push({ x, t: Date.now() });
  const oldest = mMoveHistory[0];
  const newest = mMoveHistory[mMoveHistory.length - 1];
  const dt = Math.max(1, newest.t - oldest.t);
  const dxRecent = newest.x - oldest.x;
  const velocity = -(dxRecent / CFG.DRAG_PX) / (dt / 1000);
  const inertiaStart = performance.now();
  const startVelocity = velocity * CFG.INERTIA_RATIO;
  const inertiaDur = CFG.INERTIA_DUR;
  const inertiaStartF = mFracLive;

  function inertiaStep(now) {
    const elapsed = now - inertiaStart;
    const t = Math.min(1, elapsed / inertiaDur);
    const easeT = t * (2 - t);
    const displacement = startVelocity * (inertiaDur / 1000) * easeT * 0.5;
    let frac = Math.max(0, Math.min(monthN - 1, inertiaStartF + displacement));
    monthPileEls.forEach(el => { el.style.transition = 'none'; });
    renderMonths(frac);
    if (t < 1) { mInertiaRafId = requestAnimationFrame(inertiaStep); }
    else { mInertiaRafId = null; snapToMonth(Math.round(frac)); }
  }

  if (Math.abs(startVelocity) < 0.3) snapToMonth(Math.round(mFracLive));
  else mInertiaRafId = requestAnimationFrame(inertiaStep);
}

// Month stage event listeners
monthStage.addEventListener('mousedown', e => { if (viewMode === 'months') { onMonthDragStart(e.clientX); e.preventDefault(); } });
document.addEventListener('mousemove', e => { if (mDragging) onMonthDragMove(e.clientX); });
document.addEventListener('mouseup', e => { if (mDragging) onMonthDragEnd(e.clientX); });
monthStage.addEventListener('touchstart', e => { if (viewMode === 'months') onMonthDragStart(e.touches[0].clientX); }, { passive: true });
monthStage.addEventListener('touchmove', e => { if (!mDragging) return; e.preventDefault(); onMonthDragMove(e.touches[0].clientX); }, { passive: false });
monthStage.addEventListener('touchend', e => { if (mDragging) onMonthDragEnd(e.changedTouches[0].clientX); });

// View mode switching
function buildMonthPiles() {
  groupBillsByMonth();
  monthStage.innerHTML = '';
  monthPileEls = [];
  dotsEl.innerHTML = '';
  monthKeys.forEach((key, i) => {
    monthPileEls.push(createMonthPile(key, monthGroups[key], i));
  });
  monthDotEls = monthKeys.map(() => {
    const d = document.createElement('div');
    d.className = 'dot';
    dotsEl.appendChild(d);
    return d;
  });
}

function enterMonthsView() {
  viewMode = 'months';
  clipBtn.classList.add('active');
  buildMonthPiles();
  stage.classList.add('hidden');
  monthStage.classList.add('visible');
  sectionLabel.textContent = '月份账单';
  backBtn.style.display = 'none';
  mCurrent = 0; mFracLive = 0;
  snapToMonth(0);
}

function enterMonthDetail(monthKey) {
  viewMode = 'month-detail';
  currentMonthKey = monthKey;
  const monthBills = monthGroups[monthKey];

  const currentPile = monthPileEls[mCurrent];
  const pinEl = currentPile ? currentPile.querySelector('.pile-pin') : null;
  if (pinEl) pinEl.classList.add('unpin');

  setTimeout(() => {
    monthStage.classList.remove('visible');
    stage.classList.remove('hidden');
    stage.innerHTML = '';
    dotsEl.innerHTML = '';
    cardEls.length = 0;
    dotEls.length = 0;

    const allCards = [];
    const allDots = [];
    monthBills.forEach((b, i) => {
      const card = createCard(b, i);
      const dot = createDot();
      allCards.push(card);
      allDots.push(dot);
      card.classList.add('scale-pop');
    });

    sectionLabel.textContent = `${monthKey}的账单`;
    backBtn.style.display = 'inline-block';
    current = 0; fracLive = 0;

    const STAGGER = 100;
    let added = 0;
    N = allCards.length;

    function addNextCard() {
      if (added >= allCards.length) {
        setTimeout(() => {
          cardEls.forEach(c => c.classList.remove('scale-pop', 'pop-go'));
          snapTo(0);
        }, 500);
        return;
      }
      const card = allCards[added];
      cardEls.push(card);
      dotEls.push(allDots[added]);
      cardEls.forEach(el => { el.style.transition = 'none'; });
      render(0);
      requestAnimationFrame(() => card.classList.add('pop-go'));
      added++;
      setTimeout(addNextCard, STAGGER);
    }
    addNextCard();
  }, 350);
}

function exitToAllView() {
  viewMode = 'all';
  clipBtn.classList.remove('active');
  currentMonthKey = null;
  monthStage.classList.remove('visible');
  stage.classList.remove('hidden');
  stage.innerHTML = '';
  dotsEl.innerHTML = '';
  cardEls.length = 0;
  dotEls.length = 0;
  N = bills.length;
  bills.forEach((b, i) => {
    cardEls.push(createCard(b, i));
    dotEls.push(createDot());
  });
  sectionLabel.textContent = '最近账单';
  backBtn.style.display = 'none';
  current = 0; fracLive = 0;
  snapTo(0);
}

function exitToMonthsView() {
  cardEls.forEach(card => card.classList.add('anim-collapse'));
  requestAnimationFrame(() => {
    cardEls.forEach(card => card.classList.add('collapsed'));
  });
  setTimeout(() => {
    viewMode = 'months';
    stage.classList.add('hidden');
    monthStage.classList.add('visible');
    sectionLabel.textContent = '月份账单';
    backBtn.style.display = 'none';
    const idx = monthKeys.indexOf(currentMonthKey);
    if (idx >= 0) { mCurrent = idx; mFracLive = idx; snapToMonth(idx); }
    dotsEl.innerHTML = '';
    monthDotEls = monthKeys.map(() => {
      const d = document.createElement('div');
      d.className = 'dot';
      dotsEl.appendChild(d);
      return d;
    });
    renderMonths(mFracLive);
    const targetPile = monthPileEls[mCurrent];
    if (targetPile) {
      const pinEl = targetPile.querySelector('.pile-pin');
      if (pinEl) {
        pinEl.classList.remove('unpin');
        pinEl.classList.add('repin');
        setTimeout(() => pinEl.classList.remove('repin'), 550);
      }
    }
  }, 420);
}

clipBtn.addEventListener('click', () => {
  if (viewMode === 'all') enterMonthsView();
  else if (viewMode === 'months') exitToAllView();
  else if (viewMode === 'month-detail') exitToAllView();
});

backBtn.addEventListener('click', () => {
  if (viewMode === 'month-detail') exitToMonthsView();
});

/* ══════════════════════════════════════════════════════════════
   Tab Switching + Members + Toast
══════════════════════════════════════════════════════════════ */
const tabBills = document.getElementById('tab-bills');
const tabMembers = document.getElementById('tab-members');
const tabStats = document.getElementById('tab-stats');
const tabSettings = document.getElementById('tab-settings');
const membersPanel = document.getElementById('members-panel');
const memberList = document.getElementById('member-list');
const toastEl = document.getElementById('toast');

// Content sections that belong to the bills tab
const billsSections = [
  document.querySelector('.summary'),
  document.querySelector('.carousel-section'),
];

function showToast(msg, duration = 2000) {
  document.body.appendChild(toastEl);   // 确保在 DOM 最顶层，不被 overlay 遮挡
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  setTimeout(() => toastEl.classList.remove('show'), duration);
}

function switchTab(activeTab) {
  // Update tab buttons
  [tabBills, tabMembers, tabStats, tabSettings].forEach(t => t.classList.remove('on'));
  activeTab.classList.add('on');

  // Toggle visibility
  const isBills = activeTab === tabBills;
  const isMembers = activeTab === tabMembers;
  billsSections.forEach(s => { if (s) s.style.display = isBills ? '' : 'none'; });
  membersPanel.classList.toggle('visible', isMembers);
}

tabBills.addEventListener('click', () => switchTab(tabBills));

tabMembers.addEventListener('click', async () => {
  switchTab(tabMembers);
  memberList.innerHTML = '<div class="member-loading">加载中...</div>';
  try {
    const user = await DB.getCurrentUser();
    if (!user) { memberList.innerHTML = '<div class="member-loading">请先登录</div>'; return; }

    // 直接查询 users 表（RLS 会返回所有可见用户）
    const { data: members, error } = await DB.sb
      .from('users')
      .select('id, name, email, emoji, color')
      .order('created_at', { ascending: true });

    if (error) throw error;

    if (!members || members.length === 0) {
      memberList.innerHTML = '<div class="member-loading">暂无成员</div>';
      return;
    }

    memberList.innerHTML = members.map(m => `
          <div class="member-item">
            <div class="member-avatar" style="background:${m.color || 'var(--bg4)'}">${m.emoji || '😀'}</div>
            <div class="member-info">
              <div class="member-name">${m.name || '未命名'}</div>
              ${m.email ? `<div class="member-email">${m.email}</div>` : ''}
            </div>
            ${m.id === user.id ? '<div class="member-badge">我</div>' : ''}
          </div>
        `).join('');
  } catch (err) {
    console.error('[Members] 加载失败:', err);
    memberList.innerHTML = '<div class="member-loading">加载失败</div>';
  }
});

tabStats.addEventListener('click', () => {
  switchTab(tabBills); // stay on bills view
  showToast('📊 统计功能暂未实现');
});

tabSettings.addEventListener('click', () => {
  switchTab(tabBills); // stay on bills view
  showToast('⚙️ 设置功能暂未实现');
});

/* ══════════════════════════════════════════════════════════════
   账单详情 Detail Sheet
══════════════════════════════════════════════════════════════ */
const detailOverlay = document.getElementById('detailOverlay');
let detailBill = null;

function openDetail(bill) {
  detailBill = bill;
  const el = document.getElementById('detailContent');
  const isPayer = currentUserId && bill.payer_id === currentUserId;

  // 计算每人分摊
  const memberShares = {};
  (bill.members || []).forEach(m => { memberShares[m.id] = 0; });
  (bill.items || []).forEach(item => {
    const n = (item.members || []).length || 1;
    const share = (item.price * (item.qty || 1)) / n;
    (item.members || []).forEach(m => {
      memberShares[m.id] = (memberShares[m.id] || 0) + share;
    });
  });

  // 应收/应付金额
  const otherMembers = (bill.members || []).filter(m => m.id !== bill.payer_id);
  const collectTotal = otherMembers.reduce((s, m) => s + (memberShares[m.id] || 0), 0);
  const myShare = memberShares[currentUserId] || 0;

  // 角色横幅
  let bannerHtml;
  if (isPayer) {
    bannerHtml = `<div class="detail-role-banner collect">
      <span>💰 你垫付了这笔账单，向 ${otherMembers.length} 人收款</span>
      <span class="role-amount">${fmtMoney(collectTotal)}</span>
    </div>`;
  } else if (bill._hasMeProof || bill.settled) {
    bannerHtml = `<div class="detail-role-banner paid">
      <span>✅ 已完成付款给 ${bill.payer_emoji} ${bill.payer_name}</span>
      <span class="role-amount">${fmtMoney(myShare)}</span>
    </div>`;
  } else {
    bannerHtml = `<div class="detail-role-banner pay">
      <span>📤 你需要向 ${bill.payer_emoji} ${bill.payer_name} 支付</span>
      <span class="role-amount">${fmtMoney(myShare)}</span>
    </div>`;
  }

  // 商品列表
  const itemsHtml = (bill.items || []).map(item => {
    const isMine = (item.members || []).some(m => m.id === currentUserId);
    const avatarsHtml = (item.members || []).map(m =>
      `<div class="cav">${m.emoji || '😀'}</div>`
    ).join('');
    const total = item.price * (item.qty || 1);
    return `<div class="detail-item-row${isMine ? ' mine' : ''}">
      <span class="detail-item-name">${escText(item.name)}</span>
      <span class="detail-item-qty">×${item.qty || 1}</span>
      <span class="detail-item-price">${fmtMoney(total)}</span>
      <div class="detail-item-avatars">${avatarsHtml}</div>
    </div>`;
  }).join('');

  // 分摊汇总
  const summaryHtml = (bill.members || []).map(m => {
    const isMe = m.id === currentUserId;
    const isP = m.id === bill.payer_id;
    const share = memberShares[m.id] || 0;
    return `<div class="detail-summary-row${isMe ? ' me' : ''}">
      <div class="detail-summary-avatar" style="background:${m.color || 'var(--bg4)'}">${m.emoji || '😀'}</div>
      <div class="detail-summary-name">${escText(m.name || '未知')} ${isP ? '<span class="detail-summary-label">(垫付人)</span>' : ''}</div>
      <div class="detail-summary-amount">${fmtMoney(share)}</div>
    </div>`;
  }).join('');

  // 操作按钮 — 根据角色不同
  let actionsHtml;
  if (isPayer) {
    // 收款人：结清 + 编辑 + 删除 + 查看凭证区域
    const settleBtn = bill.settled
      ? `<button class="detail-btn-settled" onclick="toggleDetailSettled('${bill.id}', true)">↩ 取消结清</button>`
      : `<button class="detail-btn-settle" onclick="toggleDetailSettled('${bill.id}', false)">✓ 标记已结清</button>`;
    actionsHtml = `
      <div class="detail-actions">
        ${settleBtn}
        <button class="detail-btn-edit" onclick="startEditBill()">✏️ 编辑</button>
        <button class="detail-btn-delete" onclick="deleteDetailBill('${bill.id}')">🗑</button>
      </div>
      <div class="proof-section" id="proofSection">
        <div class="proof-section-title">💳 付款凭证</div>
        <div id="proofList">加载中...</div>
      </div>`;
  } else {
    // 付款人：付款(上传凭证) + 异议!
    const payBtn = bill.settled
      ? `<button class="detail-btn-settled" disabled>✓ 已结清</button>`
      : `<button class="detail-btn-pay" onclick="openPayProof('${bill.id}', ${myShare})">💳 付款</button>`;
    actionsHtml = `
      <div class="proof-section" id="proofSection">
        <div class="proof-section-title">💳 我的付款凭证</div>
        <div id="proofList">加载中...</div>
        ${bill.settled ? '' : `<div class="proof-upload-area" onclick="document.getElementById('proofFileInput').click()">
          📷 点击上传 e-Transfer 截图
        </div>
        <input type="file" id="proofFileInput" accept="image/*" style="display:none" onchange="uploadProofFile('${bill.id}', this)" />`}
      </div>
      <div class="detail-actions">
        ${payBtn}
        <button class="detail-btn-protest" onclick="protestBill('${bill.id}')">😡 异议!</button>
      </div>`;
  }

  el.innerHTML = `
    <div class="detail-header">
      <div class="detail-icon">${bill.icon}</div>
      <div class="detail-title-col">
        <div class="detail-title">${escText(bill.title)}</div>
        <div class="detail-desc">${escText(bill.description)}</div>
      </div>
      <div class="detail-amount-col">
        <div class="detail-total">${fmtMoney(bill.total_amount)}</div>
        <div class="detail-per">共 ${(bill.members || []).length} 人</div>
      </div>
    </div>
    ${bannerHtml}
    <div class="detail-meta">
      <span class="detail-meta-pill">📅 ${fmtISODate(bill.date)}</span>
      <span class="detail-meta-pill">${bill.settled ? '✅ 已结清' : '⏳ 待结算'}</span>
    </div>
    <div class="detail-items-header">
      <span>商品 / 服务</span><span>数量</span><span>金额</span><span>分摊</span>
    </div>
    ${itemsHtml}
    <div class="detail-summary">
      <div class="detail-summary-title">每人分摊明细</div>
      ${summaryHtml}
    </div>
    ${actionsHtml}`;

  detailOverlay.classList.add('on');

  // 异步加载付款凭证
  loadProofList(bill.id);
}

function closeDetail(e) {
  if (e && e.target !== detailOverlay) return;
  detailOverlay.classList.remove('on');
}

detailOverlay.addEventListener('click', closeDetail);

async function toggleDetailSettled(billId, currentSettled) {
  try {
    await DB.toggleSettled(billId, !currentSettled);
    detailOverlay.classList.remove('on');
    const remoteBills = await DB.fetchMyBills();
    rebuildCarousel(remoteBills);
    showToast(currentSettled ? '已取消结清' : '✓ 已标记结清');
  } catch (e) {
    showToast('操作失败: ' + e.message);
  }
}

async function deleteDetailBill(billId) {
  if (!confirm('确定删除这条账单？删除后不可恢复。')) return;
  try {
    await DB.deleteBill(billId);
    detailOverlay.classList.remove('on');
    const remoteBills = await DB.fetchMyBills();
    rebuildCarousel(remoteBills);
    showToast('已删除');
  } catch (e) {
    showToast('删除失败: ' + e.message);
  }
}

function escText(s) {
  if (!s) return '';
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/* ══════════════════════════════════════════════════════════════
   付款凭证
══════════════════════════════════════════════════════════════ */
async function loadProofList(billId) {
  const el = document.getElementById('proofList');
  if (!el) return;
  try {
    const proofs = await DB.getPaymentProofs(billId);
    if (proofs.length === 0) {
      el.innerHTML = '<div style="font-size:12px;color:var(--label3);padding:4px 0">暂无凭证</div>';
    } else {
      el.innerHTML = proofs.map(p => `<div class="proof-item">
        <img class="proof-thumb" src="${p.image_url}" onclick="window.open('${p.image_url}','_blank')" />
        <div>
          <div>${p.user?.emoji || '😀'} ${escText(p.user?.name || '?')}</div>
          <div style="font-size:10px;color:var(--label3)">${new Date(p.created_at).toLocaleString('zh-CN')}</div>
        </div>
      </div>`).join('');
    }
  } catch (e) {
    el.innerHTML = '<div style="font-size:12px;color:var(--label3)">加载失败</div>';
  }
}

async function uploadProofFile(billId, input) {
  const file = input.files?.[0];
  if (!file) return;
  try {
    showToast('上传中...');
    await DB.uploadPaymentProof(billId, file);
    showToast('✓ 凭证已上传，等待对方确认');
    loadProofList(billId);
    // 刷新卡片状态为"已付款"
    const remoteBills = await DB.fetchMyBills();
    await markBillsWithProofs(remoteBills);
    rebuildCarousel(remoteBills);
  } catch (e) {
    showToast('上传失败: ' + e.message);
    console.error(e);
  }
  input.value = '';
}

async function openPayProof(billId, amount) {
  const amountStr = Number(amount).toFixed(2);
  try {
    await navigator.clipboard.writeText(amountStr);
    showToast(`📋 已复制 $${amountStr} 到剪贴板, 上传e-Transfer截屏完成付款🙂‍↕️`);
  } catch (e) {
    showToast(`付款金额: $${amountStr}（请手动复制）`);
  }
}

/* ══════════════════════════════════════════════════════════════
   异议！怒气系统
══════════════════════════════════════════════════════════════ */
let protestCount = 0;
let protestBillId = null;

function protestBill(billId) {
  if (protestBillId !== billId) { protestCount = 0; protestBillId = billId; }
  protestCount++;

  // 飘一个😡
  spawnAngerEmoji();

  // 每次都写入数据库
  DB.addAnger(billId).catch(e => console.error('addAnger error:', e));

  if (protestCount === 3) {
    // 第三下：显示怒气传递消息
    setTimeout(() => {
      const msg = document.createElement('div');
      msg.className = 'anger-msg';
      msg.innerHTML = '😡😡😡<br>您的怒气已经传递给<br>发起此账单的人！';
      document.body.appendChild(msg);
      setTimeout(() => msg.remove(), 3000);
    }, 400);
    protestCount = 0; // 重置，可以继续按
  }
}

function spawnAngerEmoji() {
  const emoji = document.createElement('div');
  emoji.className = 'anger-float';
  emoji.textContent = '😡';
  // 随机位置在按钮附近
  const btn = document.querySelector('.detail-btn-protest');
  if (btn) {
    const r = btn.getBoundingClientRect();
    emoji.style.left = (r.left + Math.random() * r.width) + 'px';
    emoji.style.top = (r.top - 10) + 'px';
  } else {
    emoji.style.left = (window.innerWidth / 2 - 18 + (Math.random() - 0.5) * 60) + 'px';
    emoji.style.top = (window.innerHeight * 0.6) + 'px';
  }
  document.body.appendChild(emoji);
  setTimeout(() => emoji.remove(), 1700);
}

/* ══════════════════════════════════════════════════════════════
   登录时检查未读怒气 → 怒气风暴
══════════════════════════════════════════════════════════════ */
async function checkAngerStorm() {
  try {
    const reactions = await DB.getUnseenAnger();
    if (!reactions || reactions.length === 0) return;

    let totalAnger = 0;
    const names = [];
    const ids = [];
    reactions.forEach(r => {
      totalAnger += r.anger_count;
      names.push(`${r.user?.emoji || '😡'} ${r.user?.name || '?'} ×${r.anger_count}`);
      ids.push(r.id);
    });

    // 飘怒气风暴
    for (let i = 0; i < Math.min(totalAnger, 20); i++) {
      setTimeout(() => {
        const emoji = document.createElement('div');
        emoji.className = 'anger-storm';
        emoji.textContent = '😡';
        emoji.style.left = (Math.random() * window.innerWidth) + 'px';
        emoji.style.bottom = '0px';
        document.body.appendChild(emoji);
        setTimeout(() => emoji.remove(), 2500);
      }, i * 150);
    }

    // 显示汇总消息
    setTimeout(() => {
      const msg = document.createElement('div');
      msg.className = 'anger-msg';
      msg.innerHTML = `😡 收到怒气 ×${totalAnger}<br><br><span style="font-size:13px;font-weight:400;color:var(--label2)">${names.join('<br>')}</span>`;
      document.body.appendChild(msg);
      setTimeout(() => msg.remove(), 4000);
    }, Math.min(totalAnger, 20) * 150 + 400);

    // 标记为已读
    DB.markAngerSeen(ids);
  } catch (e) {
    console.error('checkAngerStorm error:', e);
  }
}

// 页面加载后延迟检查
setTimeout(checkAngerStorm, 2000);

/* ══════════════════════════════════════════════════════════════
   账单编辑模式
══════════════════════════════════════════════════════════════ */
let editBill = null;       // 当前编辑的 bill 深拷贝
let editAllUsers = [];     // 所有可选用户
let editItemIdx = null;    // 正在编辑的行

function startEditBill() {
  if (!detailBill) return;
  // 深拷贝 bill 数据用于编辑
  editBill = JSON.parse(JSON.stringify(detailBill));
  editItemIdx = null;
  loadEditUsers().then(() => renderEditMode());
}

async function loadEditUsers() {
  const { data } = await DB.sb
    .from('users').select('id, name, emoji, color')
    .order('created_at', { ascending: true });
  editAllUsers = data || [];
}

function renderEditMode() {
  const el = document.getElementById('detailContent');

  // 商品行
  const itemsHtml = editBill.items.map((item, idx) => renderEditItemRow(item, idx)).join('');

  // 成员选择器（全局选人，然后每个item可独立调）
  const allMemberIds = new Set();
  editBill.items.forEach(item => (item.members || []).forEach(m => allMemberIds.add(m.id)));

  const memberPickerHtml = editAllUsers.map(u => {
    const sel = allMemberIds.has(u.id) ? ' selected' : '';
    return `<div class="de-member-bubble${sel}" onclick="toggleEditGlobalMember('${u.id}')">
      <div class="de-m-av" style="background:${u.color || 'var(--bg4)'}">${u.emoji || '😀'}</div>
      <div class="de-m-name">${escText(u.name || '?')}</div>
    </div>`;
  }).join('');

  el.innerHTML = `
    <div class="detail-header">
      <div class="detail-icon">${editBill.icon}</div>
      <div class="detail-title-col">
        <input class="de-input" id="de-title" value="${escText(editBill.title)}" placeholder="标题" style="width:100%;font-size:16px;font-weight:700;" />
      </div>
    </div>
    <div class="detail-summary-title" style="margin-top:8px">参与成员（点击增减）</div>
    <div class="de-member-picker" id="deMemberPicker">${memberPickerHtml}</div>
    <div class="detail-items-header">
      <span>商品 / 服务</span><span>数量</span><span>金额</span><span>分摊</span>
    </div>
    <div id="deItemsList">${itemsHtml}</div>
    <div class="de-add-item" onclick="addEditItem()">＋ 添加项目</div>
    <div class="de-save-bar">
      <button class="de-btn-back" onclick="cancelEditBill()">取消</button>
      <button class="de-btn-save" onclick="saveEditBill()">💾 保存</button>
    </div>`;
}

function renderEditItemRow(item, idx) {
  const avatarsHtml = (item.members || []).map(m =>
    `<div class="cav" style="cursor:pointer" onclick="event.stopPropagation();removeEditItemMember(${idx},'${m.id}')" title="点击移除">${m.emoji || '😀'}</div>`
  ).join('');
  const total = item.price * (item.qty || 1);
  return `<div class="detail-item-row" onclick="startEditItemRow(${idx})">
    <span class="detail-item-name">${escText(item.name)}</span>
    <span class="detail-item-qty">×${item.qty || 1}</span>
    <span class="detail-item-price">${fmtMoney(total)}</span>
    <div class="detail-item-avatars">${avatarsHtml}</div>
  </div>`;
}

function startEditItemRow(idx) {
  if (editItemIdx === idx) return;
  editItemIdx = idx;
  const item = editBill.items[idx];
  const container = document.getElementById('deItemsList');
  // 重新渲染所有行，被编辑的行展开为表单
  container.innerHTML = editBill.items.map((it, i) => {
    if (i !== idx) return renderEditItemRow(it, i);
    return `<div class="detail-item-row de-editing">
      <input class="de-input" id="de-iname-${i}" value="${escText(it.name)}" placeholder="名称" style="width:100%" />
      <input class="de-input de-qty" id="de-iqty-${i}" type="number" min="1" value="${it.qty || 1}" />
      <input class="de-input de-price" id="de-iprice-${i}" type="number" step="0.01" value="${Number(it.price).toFixed(2)}" />
      <div></div>
      <div class="de-item-actions">
        <button class="de-btn-rm" onclick="deleteEditItem(${i})">删除</button>
        <button class="de-btn-cancel" onclick="cancelEditItemRow()">取消</button>
        <button class="de-btn-ok" onclick="confirmEditItemRow(${i})">确定</button>
      </div>
    </div>`;
  }).join('');
}

function confirmEditItemRow(idx) {
  const name = document.getElementById(`de-iname-${idx}`).value.trim();
  const qty = parseInt(document.getElementById(`de-iqty-${idx}`).value) || 1;
  const price = parseFloat(document.getElementById(`de-iprice-${idx}`).value) || 0;
  if (name) {
    editBill.items[idx].name = name;
    editBill.items[idx].qty = qty;
    editBill.items[idx].price = price;
  }
  editItemIdx = null;
  document.getElementById('deItemsList').innerHTML =
    editBill.items.map((it, i) => renderEditItemRow(it, i)).join('');
}

function cancelEditItemRow() {
  editItemIdx = null;
  document.getElementById('deItemsList').innerHTML =
    editBill.items.map((it, i) => renderEditItemRow(it, i)).join('');
}

function deleteEditItem(idx) {
  editBill.items.splice(idx, 1);
  editItemIdx = null;
  document.getElementById('deItemsList').innerHTML =
    editBill.items.map((it, i) => renderEditItemRow(it, i)).join('');
}

function addEditItem() {
  // 新条目默认分配给所有当前已选成员
  const allMemberIds = new Set();
  editBill.items.forEach(item => (item.members || []).forEach(m => allMemberIds.add(m.id)));
  const defaultMembers = editAllUsers.filter(u => allMemberIds.has(u.id));
  editBill.items.push({ name: '新项目', price: 0, qty: 1, members: defaultMembers });
  document.getElementById('deItemsList').innerHTML =
    editBill.items.map((it, i) => renderEditItemRow(it, i)).join('');
  startEditItemRow(editBill.items.length - 1);
}

function toggleEditGlobalMember(uid) {
  const user = editAllUsers.find(u => u.id === uid);
  if (!user) return;
  // 检查是否已在任何 item 中
  const isIn = editBill.items.some(item => (item.members || []).some(m => m.id === uid));
  editBill.items.forEach(item => {
    if (!item.members) item.members = [];
    if (isIn) {
      // 移除（至少保留1人）
      if (item.members.length > 1) {
        item.members = item.members.filter(m => m.id !== uid);
      }
    } else {
      // 添加
      if (!item.members.some(m => m.id === uid)) {
        item.members.push({ id: user.id, name: user.name, emoji: user.emoji, color: user.color });
      }
    }
  });
  renderEditMode();
}

function removeEditItemMember(idx, uid) {
  const item = editBill.items[idx];
  if (!item || !item.members || item.members.length <= 1) return;
  item.members = item.members.filter(m => m.id !== uid);
  document.getElementById('deItemsList').innerHTML =
    editBill.items.map((it, i) => renderEditItemRow(it, i)).join('');
}

function cancelEditBill() {
  editBill = null;
  editItemIdx = null;
  openDetail(detailBill);
}

async function saveEditBill() {
  if (!editBill) return;
  try {
    const title = document.getElementById('de-title').value.trim() || editBill.title;
    const billData = {
      title,
      icon: editBill.icon,
      description: editBill.description || '',
      items: editBill.items.map(item => ({
        name: item.name,
        price: item.price,
        qty: item.qty || 1,
        member_ids: (item.members || []).map(m => m.id),
      })),
    };
    await DB.updateBill(editBill.id, billData);
    editBill = null;
    editItemIdx = null;
    detailOverlay.classList.remove('on');
    const remoteBills = await DB.fetchMyBills();
    rebuildCarousel(remoteBills);
    showToast('✓ 已保存');
  } catch (e) {
    showToast('保存失败: ' + e.message);
    console.error(e);
  }
}